-- Listage de la structure de table ddmparam. audit_types
CREATE TABLE IF NOT EXISTS `audit_types` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(10) NOT NULL COMMENT 'AC|AF|AP|AM|RP|ES',
  `label` varchar(200) NOT NULL,
  `short_label` varchar(100) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `color` varchar(20) NOT NULL DEFAULT '#2563EB',
  `icon` varchar(100) NOT NULL DEFAULT 'ti ti-clipboard-list',
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `keywords` text DEFAULT NULL COMMENT 'Mots-clés de recherche et d''identification du type d''audit',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_at_code` (`code`),
  KEY `idx_at_active` (`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Types d''audit : AC|AF|AP|AM|RP|ES';

