-- Listage de la structure de table ddmparam. audit_type_forms
CREATE TABLE IF NOT EXISTS `audit_type_forms` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `audit_type_id` bigint(20) unsigned NOT NULL COMMENT 'FK → audit_types.id  (AC=1,AF=2,AP=3,AM=4,RP=5,ES=6)',
  `phase_num` tinyint(3) unsigned NOT NULL COMMENT '1=Préparation 2=Réalisation 3=Conclusion 4=Suivi 5=Recommandations',
  `phase_label` varchar(100) NOT NULL COMMENT 'Label de la phase',
  `norme` varchar(255) DEFAULT NULL,
  `parent_id` bigint(20) unsigned DEFAULT NULL,
  `code` varchar(160) NOT NULL,
  `label` varchar(300) NOT NULL,
  `description` text DEFAULT NULL,
  `route_name` varchar(300) DEFAULT NULL,
  `url_path` varchar(400) DEFAULT NULL,
  `icon` varchar(100) NOT NULL DEFAULT 'ti ti-file-description',
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_atf_type_phase_code` (`audit_type_id`,`phase_num`,`code`),
  KEY `idx_atf_type` (`audit_type_id`),
  KEY `idx_atf_phase` (`phase_num`),
  KEY `idx_atf_parent` (`parent_id`),
  KEY `idx_atf_active` (`is_active`),
  CONSTRAINT `fk_atf_audit_type` FOREIGN KEY (`audit_type_id`) REFERENCES `audit_types` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_atf_parent` FOREIGN KEY (`parent_id`) REFERENCES `audit_type_forms` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Formulaires unifiés par type d''audit (AC|AF|AP|AM|RP|ES) et phase (1..5)';

