	(1, 1, 1, 'ETUDE / PREPARATION', 'normes iso 56', NULL, 'reunion-ouverture', 'Réunion d\'ouverture', 'Réunion officielle marquant le démarrage de la phase de préparation. Présentation de l\'équipe, méthodologie et calendrier.', 'audit.ac.preparation.reunion-ouverture', '/m/audit.core/ac/preparation/reunion-ouverture', 'ti ti-users', 10, 1, '2026-03-05 23:22:24', '2026-07-15 12:03:50'),
	(2, 1, 1, 'ETUDE / PREPARATION', 'normes iso 56', NULL, 'prise-de-connaissance', 'Prise de connaissance', 'Collecte et analyse de toutes les informations sur l\'entité auditée : organigramme, activités, textes réglementaires, rapports antérieurs.', 'audit.ac.preparation.prise-de-connaissance', '/m/audit.core/ac/preparation/prise-de-connaissance', 'ti ti-book', 20, 1, '2026-03-05 23:22:24', '2026-07-15 12:03:50'),
