INSERT INTO `pm_grilles_verification_items` (`id`, `grille_id`, `numero`, `libelle_controle`, `type_reponse`, `obligatoire`, `depend_delai`, `delai_id`, `depend_seuil`, `seuil_id`, `seuil_ac_id`, `preuves`, `actif`, `sort`, `created_at`, `updated_at`) VALUES
	(1, 1, '01', 'Plan de Passation des Marchés (PPM) — Un PPM annuel est élaboré, approuvé et publié dans les délais réglementaires.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'PPM signé, date d\'approbation, avis de publication ARMP', 1, 10, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(2, 1, '02', 'Estimation préalable et budget — Chaque marché prévu est accompagné d\'une estimation préalable budgétée et validée.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'Fiches d\'estimation, visas de la Direction Financière, ligne budgétaire allouée', 1, 20, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(3, 1, '03', 'Choix de la procédure de passation — La procédure retenue (AOO, AON, DC, gré à gré) est justifiée par les seuils et la nature du marché.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'Note de justification, tableau des seuils, avis de non-objection si requis', 1, 30, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(4, 1, '04', 'Découpage et regroupement des marchés — L\'entité n\'a pas procédé au fractionnement artificiel des marchés pour contourner les seuils.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'État récapitulatif des marchés, note explicative des lots, attestation du responsable', 1, 40, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(5, 1, '05', 'Publication du PPM et mise à jour — Le PPM est mis à jour au moins trimestriellement et les modifications sont publiées.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'PPM révisé, avis de modification ARMP/journal, dates de mise à jour', 1, 50, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(6, 2, '01', 'Élaboration du dossier d\'appel d\'offres — Le DAO est conforme aux dossiers types ARMP et comprend tous les documents obligatoires.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'DAO complet (ICAO, CPS, DPQ, CCAG, formulaires), visa ARMP si requis', 1, 60, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(7, 2, '02', 'Spécifications techniques et critères de qualification — Les spécifications techniques sont neutres, non discriminatoires et vérifiables.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'Cahier des charges, attestation de neutralité, comparaison de marché', 1, 70, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(8, 2, '03', 'Critères d\'évaluation et pondération — Les critères d\'évaluation des offres et leur pondération sont clairement définis dans le DAO avant lancement.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'Grille d\'évaluation publiée dans le DAO, procès-verbal de validation interne', 1, 80, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(9, 2, '04', 'Délai de remise des offres — Le délai minimal de remise des offres est respecté (30 jours minimum pour AOO, 15 jours pour AON).', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'Avis d\'appel d\'offres, dates de publication et de dépôt, calcul du délai', 1, 90, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(10, 2, '05', 'Publication de l\'avis d\'appel d\'offres — L\'avis est publié dans les supports obligatoires (JBO, site ARMP, journal national).', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'Coupures de presse, capture d\'écran site ARMP, récépissés de publication', 1, 100, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(11, 2, '06', 'Réponses aux demandes de clarification — Les questions des soumissionnaires reçoivent des réponses officielles communiquées à tous.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'Courriers de questions reçus, addenda publiés, preuves de diffusion à tous les candidats', 1, 110, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(12, 3, '01', 'Réception sécurisée des offres — Les offres sont reçues sous pli fermé dans un registre horodaté et conservées en lieu sûr jusqu\'à l\'ouverture.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'Registre de dépôt, accusés de réception horodatés, attestation de sécurité', 1, 120, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(13, 3, '02', 'Séance publique d\'ouverture des plis — L\'ouverture des plis est effectuée en séance publique à la date et l\'heure annoncées, en présence des membres de la commission.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'PV d\'ouverture signé par tous les membres, liste de présence, date/heure conformes à l\'avis', 1, 130, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(14, 3, '03', 'Composition régulière de la commission d\'ouverture — La commission d\'ouverture est composée conformément à la réglementation (représentants désignés, contrôleur financier).', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'Arrêté de composition de la commission, feuille d\'émargement, habilitations', 1, 140, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(15, 3, '04', 'Lecture publique des offres — Le montant de chaque offre, les remises et variantes sont lus publiquement et consignés au PV.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'PV d\'ouverture détaillé, tableau récapitulatif des offres lues', 1, 150, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(16, 3, '05', 'Gestion des offres hors délai — Les offres reçues après la date limite sont retournées sans être ouvertes et mentionnées au PV.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'PV mentionnant les offres tardives, preuves de retour aux soumissionnaires', 1, 160, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(17, 4, '01', 'Vérification de la conformité administrative — L\'évaluation administrative (caution, pièces légales, capacité juridique) est effectuée avant l\'évaluation technique.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'Grille d\'évaluation administrative remplie, PV de présélection', 1, 170, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(18, 4, '02', 'Évaluation technique des offres — L\'évaluation technique applique strictement les critères et la pondération définis dans le DAO.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'Rapport d\'évaluation technique détaillé, scores par critère, signatures des membres', 1, 180, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(19, 4, '03', 'Évaluation financière et correction arithmétique — Les offres financières des soumissionnaires techniquement qualifiés sont évaluées et les erreurs arithmétiques corrigées selon les règles du DAO.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'Tableau comparatif des offres financières, corrections arithmétiques documentées', 1, 190, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(20, 4, '04', 'Rapport d\'évaluation et proposition d\'attribution — Le rapport d\'évaluation est complet, signé par tous les membres et propose l\'attributaire le mieux-disant conforme.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'Rapport d\'évaluation final signé, décision d\'attribution proposée, classement des offres', 1, 200, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(21, 4, '05', 'Non-discrimination et confidentialité — L\'évaluation est conduite sans discrimination et la confidentialité des offres est préservée jusqu\'à l\'attribution.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'Déclarations de confidentialité des membres, absence de conflits d\'intérêt documentée', 1, 210, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(22, 4, '06', 'Demande d\'éclaircissements — Les demandes d\'éclaircissement aux soumissionnaires sont faites par écrit et ne modifient pas substantiellement les offres.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'Courriers de demande d\'éclaircissement, réponses reçues, traçabilité', 1, 220, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(23, 5, '01', 'Publication des résultats d\'attribution — Les résultats d\'attribution sont publiés dans les délais réglementaires (5 jours maximum après décision).', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'Avis d\'attribution publié, date de publication, supports utilisés', 1, 230, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(24, 5, '02', 'Délai de recours et gestion des plaintes — Le délai de recours (5 jours ouvrables minimum après publication) est respecté avant la signature du contrat.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'Journal de publication, date de signature du contrat, preuves du délai respecté', 1, 240, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(25, 5, '03', 'Élaboration et signature du contrat — Le contrat reprend fidèlement les conditions du DAO et de l\'offre retenue, sans modifications substantielles.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'Contrat signé, comparaison contrat/DAO/offre, visa juridique', 1, 250, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(26, 5, '04', 'Approbation réglementaire du contrat — Le contrat est approuvé par l\'autorité compétente (Contrôleur Financier, ARMP selon seuils) avant tout démarrage.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'Visa du contrôleur financier, avis de non-objection ARMP, date d\'approbation', 1, 260, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(27, 5, '05', 'Notification et ordre de service de démarrage — La lettre de notification et l\'ordre de service de démarrage sont transmis à l\'attributaire dans les délais.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'Lettre de notification signée et accusé de réception, ordre de service daté', 1, 270, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(28, 5, '06', 'Garanties contractuelles — Les garanties requises (caution de bonne exécution, avance de démarrage) sont constituées avant tout paiement.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'Cautions bancaires, dates de constitution, montants conformes au contrat', 1, 280, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(29, 6, '01', 'Mise en place du dispositif de suivi — Un responsable de suivi du marché est désigné et son rôle est formalisé.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'Désignation officielle du responsable, fiche de poste, rapport de prise de fonction', 1, 290, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(30, 6, '02', 'Respect des délais d\'exécution — L\'exécution respecte le calendrier contractuel et tout retard fait l\'objet d\'une pénalité ou d\'un avenant motivé.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'Planning d\'exécution, rapports d\'avancement, PV de constat de retard, calcul des pénalités', 1, 300, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(31, 6, '03', 'Avenants et modifications du marché — Les avenants sont justifiés, soumis à approbation préalable et ne dépassent pas les seuils réglementaires (30% maximum).', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'Avenants signés, justifications techniques/financières, approbation du contrôleur, taux d\'avenant calculé', 1, 310, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(32, 6, '04', 'Contrôle qualité des prestations — Des contrôles réguliers de la qualité des prestations sont effectués et documentés.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'Rapports de contrôle qualité, PV d\'inspection, relevés de conformité technique', 1, 320, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(33, 6, '05', 'Sous-traitance — Toute sous-traitance est déclarée, approuvée et ne dépasse pas les limites contractuelles.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'Contrats de sous-traitance approuvés, déclarations, limites respectées', 1, 330, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(34, 7, '01', 'Réception provisoire — La réception provisoire est effectuée par une commission compétente qui vérifie la conformité aux spécifications.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'PV de réception provisoire signé, liste de la commission, réserves éventuelles documentées', 1, 340, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(35, 7, '02', 'Réception définitive — La réception définitive intervient après levée de toutes les réserves dans le délai de garantie contractuel.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'PV de réception définitive, preuves de levée des réserves, respect du délai de garantie', 1, 350, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(36, 7, '03', 'Traitement des demandes de paiement — Les demandes de paiement sont vérifiées et les paiements effectués dans le délai contractuel (60 jours maximum).', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'Décomptes et factures reçus, dates de réception et de paiement, calcul des délais, intérêts moratoires si dépassés', 1, 360, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(37, 7, '04', 'Libération des garanties — Les garanties (retenue de garantie, caution) sont libérées après réception définitive et dans les délais contractuels.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'Demandes de libération, mainlevées de caution, dates de libération conformes au contrat', 1, 370, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(38, 7, '05', 'Décompte final et solde — Le décompte final est établi, approuvé et reflète toutes les prestations réalisées conformément au marché.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'Décompte final approuvé, réconciliation avec le budget initial, visa financier', 1, 380, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(39, 8, '01', 'Constitution et conservation du dossier de marché — Le dossier complet du marché (DAO, offres, PV, contrat, avenants, réceptions, paiements) est conservé et accessible.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'Index du dossier de marché, inventaire des pièces, localisation physique/électronique', 1, 390, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(40, 8, '02', 'Rapport annuel de passation — L\'entité produit et transmet à l\'ARMP son rapport annuel de passation dans les délais.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'Rapport annuel de passation, accusé de réception ARMP, date de transmission', 1, 400, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(41, 8, '03', 'Accès à l\'information et transparence — Les informations obligatoires (PPM, attributions, contrats) sont publiées sur les supports réglementaires.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'Publications ARMP, affichage institutionnel, portail de transparence si disponible', 1, 410, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(42, 8, '04', 'Déclarations de conflits d\'intérêt — Tous les membres des commissions ont signé des déclarations de non-conflit d\'intérêt pour chaque marché.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'Formulaires de déclaration signés, archivés par marché', 1, 420, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(43, 8, '05', 'Traitement des recours et plaintes — Les recours reçus sont traités dans les délais réglementaires et les décisions communiquées.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'Registre des recours, décisions rendues, preuves de notification aux parties', 1, 430, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
	(44, 8, '06', 'Sanctions et liste noire — Les prestataires défaillants ont fait l\'objet de signalement à l\'ARMP pour inscription sur la liste noire.', 'conformite', 1, 0, NULL, 0, NULL, NULL, 'PV de constat de défaillance, lettres de signalement à l\'ARMP, suivi du dossier', 1, 440, '2026-07-10 08:37:59', '2026-07-10 08:37:59'),
