	(65, 10, '02', 'Le Plan de Passation des Marchés Publics (PPMP) a été validé par l\'organe de contrôle compétent (CCMP), conformément à l\'Article 24, alinéa 1er de la loi n° 2020-26 du 29 septembre 2020 et à l\'Article 2, alinéa 1er, point 1 du Décret n° 2020-597 du 23 décembre 2020', 'conformite', 1, 0, NULL, 0, NULL, NULL, NULL, 1, 11, '2026-07-10 14:21:49', '2026-07-10 14:21:49'),
	(66, 10, '03', 'Conformité du Plan de Passation des Marchés (PPM) initial et de sa validation par la CCMP, ainsi que de sa révision, le cas échéant, conformément aux exigences de l\'Article 24 de la loi n° 2020-26 du 29 septembre 2020', 'conformite', 1, 0, NULL, 0, NULL, NULL, NULL, 1, 12, '2026-07-10 14:21:49', '2026-07-10 14:21:49'),
	(67, 10, '04', 'Le Plan de Passation des Marchés Publics (PPMP) est dûment publié sur le SIGMAP (www.marches-publics.bj), conformément aux exigences de l\'Article 24 de la loi 2020-26 du 29 septembre 2020).', 'conformite', 1, 0, NULL, 0, NULL, NULL, NULL, 1, 13, '2026-07-10 14:21:49', '2026-07-10 14:21:49'),
	(68, 10, '05', 'Les différents marchés échantillonnés pour l\'audit figurent dans le Plan de Passation des Marchés Publics (PPMP)', 'conformite', 1, 0, NULL, 0, NULL, NULL, NULL, 1, 14, '2026-07-10 14:21:49', '2026-07-10 14:21:49'),
	(69, 10, '06', 'Les marchés inscrits au Plan de Passation des Marchés Publics (PPMP) ne sont pas fractionnés, conformément à l\'Article 24, alinéa 7 de la loi n° 2020-26 du 29 septembre 2020', 'conformite', 1, 0, NULL, 0, NULL, NULL, NULL, 1, 15, '2026-07-10 14:21:49', '2026-07-10 14:21:49'),
	(70, 10, '07', 'Les révisions successives du Plan de Passation des Marchés Publics (PPMP) comprennent notamment les éléments suivants : (i) une description succincte des activités, (ii) les modes, les méthodes et les techniques de sélection à appliquer, (iii) le montant prévisionnel hors taxes, (iv) les calendriers et toute autre information pertinente en rapport avec la passation des marchés conformément à l\'article 24 de la loi n°2020-26 du 29 septembre 2020', 'conformite', 1, 0, NULL, 0, NULL, NULL, NULL, 1, 16, '2026-07-10 14:21:49', '2026-07-10 14:21:49'),
	(71, 10, '08', 'Les révisions successives du Plan de Passation des Marchés Publics (PPMP), lorsqu\'elles existent, ont été soumises à la validation préalable de l\'organe de contrôle compétent (CCMP), conformément à l\'Article 2 du Décret n°2020-597 du 23 décembre 2020.', 'conformite', 1, 0, NULL, 0, NULL, NULL, NULL, 1, 17, '2026-07-10 14:21:49', '2026-07-10 14:21:49'),
	(72, 10, '09', 'Les révisions validées du Plan de Passation des Marchés Publics (PPMP) ont été publiées sur la plateforme SIGMAP (www.marches-publics.bj), conformément aux exigences de l\'Article 24 de la loi 2020-26 du 29 septembre 2020).', 'conformite', 1, 0, NULL, 0, NULL, NULL, NULL, 1, 18, '2026-07-10 14:21:49', '2026-07-10 14:21:49'),
