	(78, 11, '05', 'Conformité de la publication du procès-verbal d\'ouverture des plis dans le Journal des Marchés Publics, le quotidien du service public, sur le portail web des marchés publics et, le cas échéant, dans une publication internationale à grande diffusion (pour les appels d\'offres et les demandes de propositions), conformément à l\'Article 70 de la loi n° 2020-26 du 29 septembre 2020 et à la Circulaire n° 2020-02/PR/ARMP/SP/DRAJ/SRR/SA du 30 janvier 2020.', 'conformite', 1, 0, NULL, 0, NULL, NULL, NULL, 1, 14, '2026-07-10 14:21:49', '2026-07-10 14:21:49'),
	(79, 11, '06', 'Conformité de la publication du procès-verbal d\'attribution provisoire dans le Journal des Marchés Publics, le quotidien du service public, sur le portail web des marchés publics et, le cas échéant, dans une publication internationale à grande diffusion (pour les appels d\'offres et les demandes de propositions), conformément à l\'Article 78 de la loi n° 2020-26 du 29 septembre 2020 et à la Circulaire n° 2020-02/PR/ARMP/SP/DRAJ/SRR/SA du 30 janvier 2020.', 'conformite', 1, 0, NULL, 0, NULL, NULL, NULL, 1, 15, '2026-07-10 14:21:49', '2026-07-10 14:21:49'),
	(80, 11, '07', 'Conformité de la publication de l\'avis d\'attribution définitive dans le Journal des Marchés Publics, le quotidien du service public, sur le portail web des marchés publics et, le cas échéant, dans une publication internationale à grande diffusion (pour les appels d\'offres et les demandes de propositions), ou de l\'affichage de l\'avis d\'attribution définitive au siège, à la préfecture ou mairie, dans les chambres de métiers et institutions consulaires, et sur le portail web des marchés publics (pour la DRP et la DC le cas échéant), conformément à l\'Article 87 de la loi n° 2020-26 du 29 septembre 2020, à l\'Article 13 du décret n° 2020-605 du 23 décembre 2020 et à la Circulaire n° 2020-02/PR/ARMP/SP/DRAJ/SRR/SA du 30 janvier 2020.', 'conformite', 1, 0, NULL, 0, NULL, NULL, NULL, 1, 16, '2026-07-10 14:21:49', '2026-07-10 14:21:49'),
