	(277, 19, '71', 'Conformité de l\'exhaustivité des rubriques renseignées dans le CCAP par référence aux clauses générales, aux exigences de l\'article 46 de la loi n° 2020-26 du 29 septembre 2020 et des documents types en vigueur à la date sous revue.', 'conformite', 1, 0, NULL, 0, NULL, NULL, NULL, 1, 80, '2026-07-10 14:29:48', '2026-07-10 14:29:48'),
	(278, 19, '72', 'Conformité des termes du commerce international requis aux Incoterms en vigueur, conformément à l\'article 46 de la loi n° 2020-26 du 29 septembre 2020 et aux documents types en vigueur à la date sous revue.', 'conformite', 1, 0, NULL, 0, NULL, NULL, NULL, 1, 81, '2026-07-10 14:29:48', '2026-07-10 14:29:48'),
	(279, 19, '73', 'Conformité des dispositions du règlement des litiges aux exigences de l\'article 120 de la loi n° 2020-26 du 29 septembre 2020 et des documents types en vigueur à la date sous revue.', 'conformite', 1, 0, NULL, 0, NULL, NULL, NULL, 1, 82, '2026-07-10 14:29:48', '2026-07-10 14:29:48'),
	(280, 19, '74', 'Conformité de la prescription d\'une liste exhaustive des documents nécessaires pour la livraison, aux exigences des documents types en vigueur à la date sous revue.', 'conformite', 1, 0, NULL, 0, NULL, NULL, NULL, 1, 83, '2026-07-10 14:29:48', '2026-07-10 14:29:48'),
	(281, 19, '75', 'Conformité de la formule d\'actualisation ou de révision des prix prescrite dans le CCAP, aux exigences de l\'article 97 de la loi n° 2020-26 du 29 septembre 2020 et des documents types en vigueur à la date sous revue.', 'conformite', 1, 0, NULL, 0, NULL, NULL, NULL, 1, 84, '2026-07-10 14:29:48', '2026-07-10 14:29:48'),
	(282, 19, '76', 'Conformité de la fixation du montant de l\'avance de démarrage dans le CCAP, aux exigences de l\'article 111 de la loi n° 2020-26 du 29 septembre 2020 et des documents types en vigueur à la date sous revue.', 'conformite', 1, 0, NULL, 0, NULL, NULL, NULL, 1, 85, '2026-07-10 14:29:48', '2026-07-10 14:29:48'),
	(283, 19, '77', 'Conformité de la fixation du taux de la redevance de régulation dans le CCAP, aux exigences de l\'article 99 de la loi n° 2020-26 du 29 septembre 2020 et des documents types en vigueur à la date sous revue.', 'conformite', 1, 0, NULL, 0, NULL, NULL, NULL, 1, 86, '2026-07-10 14:29:48', '2026-07-10 14:29:48'),
	(284, 19, '78', 'Conformité de la fixation du taux de la garantie de bonne exécution dans le CCAP, aux exigences de l\'article 91 de la loi n° 2020-26 du 29 septembre 2020 et des documents types en vigueur à la date sous revue.', 'conformite', 1, 0, NULL, 0, NULL, NULL, NULL, 1, 87, '2026-07-10 14:29:48', '2026-07-10 14:29:48'),
	(285, 19, '79', 'Conformité de la fixation du montant plafond des pénalités de retard dans le CCAP, aux exigences de l\'article 113 de la loi n° 2020-26 du 29 septembre 2020 et des documents types en vigueur à la date sous revue.', 'conformite', 1, 0, NULL, 0, NULL, NULL, NULL, 1, 88, '2026-07-10 14:29:48', '2026-07-10 14:29:48'),
	(286, 19, '80', 'Conformité de l\'exhaustivité des informations renseignées dans le modèle de marché, en cohérence avec l\'objet de l\'appel d\'offres, le CCAP et les exigences des articles 46 et 83 de la loi n° 2020-26 du 29 septembre 2020 et des documents types en vigueur à la date sous revue.', 'conformite', 1, 0, NULL, 0, NULL, NULL, NULL, 1, 89, '2026-07-10 14:29:48', '2026-07-10 14:29:48'),
	(287, 19, '81', 'Conformité de l\'énumération et de l\'ordre de priorité des pièces contractuelles, aux exigences de l\'article 83 de la loi n° 2020-26 du 29 septembre 2020 et des documents types en vigueur à la date sous revue.', 'conformite', 1, 0, NULL, 0, NULL, NULL, NULL, 1, 90, '2026-07-10 14:29:48', '2026-07-10 14:29:48'),
	(288, 19, '82', 'Conformité des mentions obligatoires du modèle de contrat, aux exigences de l\'article 99 de la loi n° 2020-26 du 29 septembre 2020 et des documents types en vigueur à la date sous revue.', 'conformite', 1, 0, NULL, 0, NULL, NULL, NULL, 1, 91, '2026-07-10 14:29:48', '2026-07-10 14:29:48'),
	(289, 19, '83', 'Conformité des conditions d\'entrée en vigueur fixées dans le modèle de contrat, aux exigences de l\'article 87 de la loi n° 2020-26 du 29 septembre 2020 et des documents types en vigueur à la date sous revue.', 'conformite', 1, 0, NULL, 0, NULL, NULL, NULL, 1, 92, '2026-07-10 14:29:48', '2026-07-10 14:29:48'),
	(290, 19, '84', 'Conformité des signataires du modèle de contrat aux exigences de l\'article 85 de la loi n° 2020-26 du 29 septembre 2020, du décret n° 2020-596 du 23 décembre 2020 et des documents types en vigueur à la date sous revue.', 'conformite', 1, 0, NULL, 0, NULL, NULL, NULL, 1, 93, '2026-07-10 14:29:48', '2026-07-10 14:29:48'),
