	(6, 'Demande de Cotation (DC)', 4000001.00, 10000000.00, '>', '<=', 'DC', 'Montant > 4 000 000 F et ≤ 10 000 000 F HT. Consultation d\'au moins 3 soumissionnaires.', NULL, NULL, 'blue', 2, '2026-06-08 18:52:03', '2026-06-08 18:52:03'),
