	(8, 'Seuil de passation — Appel d\'offres', NULL, NULL, '>=', NULL, 'AOO', 'Montant ≥ seuil de passation de la catégorie AC. Procédures formelles (AOO, AOR, GAG). Défini par catégorie dans Seuils par AC.', NULL, NULL, 'red', 4, '2026-06-08 18:52:03', '2026-06-08 18:52:03');
